clear;
clc; 
close all;

totalBandwidthHz = 1e6; 
fdmaChannelHz = 200e3;
tdmaSlots = 8;
processingGain = 64;
targetSIRdB = 7;
fdmaUsers = floor(totalBandwidthHz / fdmaChannelHz);
tdmaUsers = tdmaSlots;
targetSIR = 10^(targetSIRdB / 10);
cdmaUsers = floor(1 + processingGain / targetSIR);
fprintf('Illustrative maximum supported users\n'); %[output:94ede981]
fprintf('FDMA: %d users\n', fdmaUsers); %[output:37407071]
fprintf('TDMA: %d users\n', tdmaUsers); %[output:32639539]
fprintf('CDMA: %d users at a target SIR of %.1f dB\n\n', ... %[output:group:93c05c58] %[output:0edfb9a1]
    cdmaUsers, targetSIRdB); %[output:group:93c05c58] %[output:0edfb9a1]

K = 2:30;
sirLinear = processingGain ./ (K - 1);
sirDb = 10 * log10(sirLinear);

method = ["FDMA"; "TDMA"; "CDMA"];
supportedUsers = [fdmaUsers; tdmaUsers; cdmaUsers];
results = table(method, supportedUsers);
disp(results); %[output:895825e2]

figure; %[output:324c7a3e]
bar(categorical(method), supportedUsers); %[output:324c7a3e]
ylabel('Illustrative maximum supported simultaneous users'); %[output:324c7a3e]
title('FDMA, TDMA and CDMA: Capacity Estimate'); %[output:324c7a3e]
grid on; %[output:324c7a3e]

figure; %[output:92568197]
plot(K, sirDb, 'o-', 'LineWidth', 1.5); %[output:92568197]
hold on; %[output:92568197]
yline(targetSIRdB, '--r', 'Target SIR'); %[output:92568197]
xlabel('Number of simultaneous CDMA users (K)'); %[output:92568197]
ylabel('Estimated SIR (dB)'); %[output:92568197]
title('Estimated CDMA SIR versus Number of Users'); %[output:92568197]
grid on; %[output:92568197]
hold off; %[output:92568197]


